from lib import *
S = SS('u63')
R = J('u63'); a = R['asm']; n = a['n']; vec = a['vec']
steps = [
    step("map 可以改变元素类型:i32 → String 得 [\"#1\",…,\"#6\"];filter 不改变类型。对 v.iter() 来说元素是 &i32,filter 的闭包拿到的是元素的引用,所以参数类型是 &&i32(两次调用都打印出 &&i32),结果仍是 Vec<&i32>。先 copied() 后,filter 的参数才是 &i32,可以直接写 x % 2。", t=tl(S(1)), done=lidx(S(1), 'map i32', '&&i32', 'copied'), kv=KV([['iter().filter 的参数', '&&i32'], ['copied().filter 的参数', '&i32']], ['iter().filter 的参数'])),
    step("直接写 v.iter().filter(|x| x % 2 == 0) 报 error[E0369]: cannot calculate the remainder of `&&{integer}` divided by `{integer}`,help 建议对左边解引用。", t=tl(S(1)), mark=lidx(S(1), 'error[E0369]'), kv=KV([['x % 2', 'E0369:&&i32 不能取余']], ['x % 2'])),
    step("filter_map 把「解析 + 丢弃失败」合成一步:[\"10\",\"x\",\"30\",\"\",\"50\"] 得 [10,30,50];map(parse).flatten() 结果相同(Result 实现了 IntoIterator,Err 产出空);而 collect 成 Result<Vec<_>, _> 则整体失败:Err(ParseIntError { kind: InvalidDigit })。", t=tl(S(2)), done=lidx(S(2), 'filter_map', 'flatten'), mark=lidx(S(2), 'Err('), kv=KV([['filter_map', '[10, 30, 50]'], ['collect::<Result<_,_>>', '遇到第一个 Err 就失败']], ['collect::<Result<_,_>>'])),
    step("fold 的累加器类型可以和元素不同:i32 元素用 String 累加得 \"10-3-2\",用元组 (和, 个数) 得 (15, 3)。顺序有影响:[10,3,2] 上 fold(0, a*2+x) 从左到右得 48,rfold 从右到左得 24。reduce 在空序列上返回 None,fold(0, …) 返回 0;scan 保留每一步中间状态 [10,13,15]。", t=tl(S(3)), done=lidx(S(3), '48', '"10-3-2"', '(15, 3)', 'reduce', 'scan'), kv=KV([['fold 左到右', '48'], ['rfold 右到左', '24'], ['空序列 reduce', 'None']], ['fold 左到右'])),
    step("try_fold 遇到失败立即停止:u8 序列 [100,100,50,10,1,1] 用 checked_add 累加,累加到第 4 个元素(250+10)溢出,返回 None,只看了 4 个元素,最后两个没处理;不溢出的 [1,2,3] 得 Some(6)。", t=tl(S(4)), mark=lidx(S(4), 'None'), done=lidx(S(4), 'Some(6)'), kv=KV([['溢出时', '短路返回 None'], ['看过的元素', '4 / 6']], ['溢出时'])),
    step(f"汇编对比(-O,aarch64):fold 写法与 for 循环写法 —— sum_for {n['sum_for']} 条指令、sum_fold {n['sum_fold']} 条,都生成了向量指令({vec['sum_for']} / {vec['sum_fold']} 条);两者规范化标签后{'逐行相同' if a['fm'] else '并不逐行相同'}。另一个写法完全相同的 sum_iter 被 LLVM 合并成了 sum_fold 的别名(_sum_iter = _sum_fold)。", t=tl(S(5)), done=lidx(S(5), 'sum_for', 'sum_fold', '别名'), b=bars([['sum_for', n['sum_for'], str(n['sum_for'])], ['sum_fold', n['sum_fold'], str(n['sum_fold'])]], max(n['sum_for'], n['sum_fold']) + 10, done=[0, 1]), kv=KV([['for 循环', f"{n['sum_for']} 条"], ['fold', f"{n['sum_fold']} 条"], ['两者', '都向量化']], ['两者'])),
    step(f"map + filter + fold 链与手写的 for + if 循环:sum_map_filter {n['sum_map_filter']} 条指令(向量指令 {vec['sum_map_filter']} 条)、sum_manual {n['sum_manual']} 条(向量指令 {vec['sum_manual']} 条);向量指令条数相同,总数相差 {abs(n['sum_map_filter'] - n['sum_manual'])} 条,不是逐行相同。结论只限于这一个例子:链没有变成没法向量化的慢代码,但也不保证和手写循环字节一致。", t=tl(S(5)), done=lidx(S(5), 'sum_map_filter', 'sum_manual'), b=bars([['sum_map_filter', n['sum_map_filter'], str(n['sum_map_filter'])], ['sum_manual', n['sum_manual'], str(n['sum_manual'])]], max(n['sum_map_filter'], n['sum_manual']) + 10, done=[0, 1]), kv=KV([['链 vs 手写', f"{n['sum_map_filter']} vs {n['sum_manual']} 条"]], ['链 vs 手写'])),
]
A = mkart('u63', 63, 'Rust,Iterator,map,filter,fold,真实验证,动画演示',
    f'用真实运行验证 map、filter、fold:map 改变元素类型、iter().filter 的参数是 &&i32(直接取余报 E0369);filter_map 与 flatten 丢弃失败项、collect 成 Result 则整体失败;fold 累加器类型自由、顺序影响结果(48 对 24)、reduce 对空序列返回 None;try_fold 短路;aarch64 汇编里 fold 与 for 循环({n["sum_fold"]} 对 {n["sum_for"]} 条指令)都向量化。',
    '这三个最常用的迭代器适配器,细节一点也不少:闭包拿到的是引用还是值?fold 的顺序有什么影响?出错能不能提前停?链写出来的机器码和手写循环一样吗?这篇都用真实编译与运行来回答。',
    [('&&i32', 'v.iter().filter 的闭包参数类型'), ('48 对 24', '[10,3,2] 上 fold 与 rfold 同一个闭包的结果'), (f"{n['sum_fold']} 对 {n['sum_for']}", 'fold 与 for 循环的汇编指令条数(都向量化)')],
    [('类型与引用', '<p>惰性的具体含义见<a href="rust-iterator-lazy.html">Iterator 的惰性执行</a>。</p>'), ('filter_map 与 collect', None), ('fold 与 reduce', None), ('try_fold', None), ('汇编对比', '<p>指令条数来自 aarch64 的 -O 汇编,换平台数字会不同。</p>')],
    steps, [ENV_U + '。汇编用 rustc --emit=asm -O 生成,并规范化局部标签后比较', '没有验证:x86_64 平台的汇编、浮点数 fold(向量化会因结合律受限)、sum()/product() 的内部实现、大数据量下三种写法的运行时间(只比较了汇编)'], 'map / filter / fold')
